import { createSubcontractorCompany as createSubcontractorCompanyaFunc } from '~/client';
import type { CreateSubcontractorCompanyRequest, CreateSubcontractorCompanyResponse } from '~/client';

export const useCreateSubcontractorCompany = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: CreateSubcontractorCompanyRequest): Promise<CreateSubcontractorCompanyResponse> =>
      createSubcontractorCompanyaFunc({
        composable: '$fetch',
        body: data,
      }),
    onSuccess: async (data) => {
      showToastSuccess('Subcontractor company created successfully');
      await navigateTo({
        name: 'subcontractor-companies-id',
        params: { id: data.id },
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createSubcontractorCompany: mutateAsync,
    isCreateSubcontractorCompanyLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
