<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Create New Subcontractor Company" />
    <section class="flex flex-col gap-4">
      <GoBackButton subject="subcontractor companies" :fallback-to="{ name: 'subcontractor-companies' }" />
      <SubcontractorCompanyForm
        :is-saving="isCreateSubcontractorCompanyLoading"
        submit-label="Create Company"
        :cancel-to="{ name: 'subcontractor-companies' }"
        :on-submit="onSubmit"
      />
    </section>
  </section>
</template>

<script lang="ts" setup>
import type { SubcontractorCompanyFormValues } from '~/constants/validationSchemas/subcontractorCompanyForm';
import { useCreateSubcontractorCompany } from '~/mutations/subcontractor-company/create';

definePageMeta({
  roles: ['admin'],
  skipNavJourney: true,
});

useSeoMeta({
  title: 'Create Subcontractor Company',
  description: 'Create a new subcontractor company in the system.',
});

const { createSubcontractorCompany, isCreateSubcontractorCompanyLoading } = useCreateSubcontractorCompany();

const onSubmit = async (values: SubcontractorCompanyFormValues) => {
  await createSubcontractorCompany(values);
};
</script>
